import json
# 5x5 tiles of 4x4 interiors; separators at indices 4,9,14,19
keys=[2,3,4,6,7]
support={(0,2),(1,0),(1,1),(1,2),(1,3),(2,1),(2,2),(3,2)}
grid=[]
for tr in range(5):
    for lr in range(4):
        row=[]
        for tc in range(5):
            for lc in range(4): row.append(keys[tr] if (lr,lc) in support else 0)
            if tc<4: row.append(5)
        grid.append(row)
    if tr<4: grid.append([5]*24)
assert len(grid)==24 and all(len(r)==24 for r in grid)
print(json.dumps({'action':'submit','grid':grid},separators=(',',':')))

